import{_ as a,a0 as l,w as s,s as p,ao as d,I as o,x as t,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"使用 GSConnect 将 Android 手机连接到 Fedora 系统 | LCTT x X-CMD","titleTemplate":false,"description":"使用 GSConnect 将 Android 手机连接到 Fedora 系统 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 GSConnect 将 Android 手机连接到 Fedora 系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 GSConnect 将 Android 手机连接到 Fedora 系统 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200207 Connect Fedora to your Android phone with GSConnect","title":"使用 GSConnect 将 Android 手机连接到 Fedora 系统","tag":"202002","desc":""},"relativePath":"202002/20200207 Connect Fedora to your Android phone with GSConnect.md","filePath":"[post].md"}'),u={name:"202002/20200207 Connect Fedora to your Android phone with GSConnect.md"};function g(f,n,m,C,S,b){const e=l("Link");return s(),p("div",null,[n[32]||(n[32]=d('<h1 id="使用-gsconnect-将-android-手机连接到-fedora-系统" tabindex="-1">使用 GSConnect 将 Android 手机连接到 Fedora 系统 <a class="header-anchor" href="#使用-gsconnect-将-android-手机连接到-fedora-系统" aria-label="Permalink to “使用 GSConnect 将 Android 手机连接到 Fedora 系统”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/12/gsconnect-816x345.jpg" alt=""></p><p>苹果和微软公司都不同程度的提供了桌面产品与移动设备集成。Fedora 提供了类似甚至更高集成度的工具——GSConnect。它可以让你将安卓手机和你的 Fedora 桌面配对并使用。请继续阅读，以了解更多关于它的情况以及它是如何工作的信息。</p><h3 id="gsconnect-是什么" tabindex="-1">GSConnect 是什么? <a class="header-anchor" href="#gsconnect-是什么" aria-label="Permalink to “GSConnect 是什么?”">​</a></h3><p>GSConnect 是针对 GNOME 桌面定制的 KDE Connect 程序。KDE Connect 可以使你的设备能够互相通信。但是，在 Fedora 默认的 GNOME 桌面上安装它需要安装大量的 KDE 依赖。</p><p>GSConnect 是一个 KDE Connect 的完整实现，其以 GNOME shell 的拓展形式出现。安装后，GSConnect 允许你执行以下操作及更多：</p><ul><li>在计算机上接收电话通知并回复信息</li><li>用手机操纵你的桌面</li><li>在不同设备之间分享文件与链接</li><li>在计算机上查看手机电量</li><li>让手机响铃以便你能找到它</li></ul><h3 id="设置-gsconnect-扩展" tabindex="-1">设置 GSConnect 扩展 <a class="header-anchor" href="#设置-gsconnect-扩展" aria-label="Permalink to “设置 GSConnect 扩展”">​</a></h3><p>设置 GSConnect 需要安装两个组件：计算机上的 GSConnect 扩展和 Android 设备上的 KDE Connect 应用。</p>',9)),o("p",null,[n[2]||(n[2]=t("首先，从 GNOME Shell 扩展网站上安装 ",-1)),r(e,{href:"https://extensions.gnome.org/extension/1319/gsconnect/"},{default:i(()=>[...n[0]||(n[0]=[t("GSConnect",-1)])]),_:1}),n[3]||(n[3]=t(" 扩展。（Fedora Magazine 有一篇关于",-1)),r(e,{href:"https://fedoramagazine.org/install-gnome-shell-extension/"},{default:i(()=>[...n[1]||(n[1]=[t("如何安装 GNOME Shell 扩展",-1)])]),_:1}),n[4]||(n[4]=t("的文章，可以帮助你完成这一步。）",-1))]),o("p",null,[n[7]||(n[7]=t("KDE Connect 应用程序可以在 Google 的 ",-1)),r(e,{href:"https://play.google.com/store/apps/details?id=org.kde.kdeconnect_tp"},{default:i(()=>[...n[5]||(n[5]=[t("Play 商店",-1)])]),_:1}),n[8]||(n[8]=t("上找到。它也可以在 FOSS Android 应用程序库 ",-1)),r(e,{href:"https://f-droid.org/en/packages/org.kde.kdeconnect_tp/"},{default:i(()=>[...n[6]||(n[6]=[t("F-Droid",-1)])]),_:1}),n[9]||(n[9]=t(" 上找到。",-1))]),n[33]||(n[33]=d('<p>一旦安装了这两个组件，就可以配对两个设备。安装扩展后它在你的系统菜单中显示为“<ruby>移动设备<rt>Mobile Devices</rt></ruby>”。单击它会出现一个下拉菜单，你可以从中访问“<ruby>移动设置<rt>Mobile Settings</rt></ruby>”。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/01/within-the-menu-1024x576.png" alt=""></p><p>你可以在这里用 GSConnect 查看并管理已配对的设备。进入此界面后，需要在 Android 设备上启动应用程序。</p><p>你可以在任意一台设备上进行配对初始化，在这里我们从 Android 设备连接到计算机。点击应用程序上的“刷新”，只要两个设备都在同一个无线网络环境中，你的 Android 设备便可以搜索到你的计算机。现在可以向桌面发送配对请求，并在桌面上接受配对请求以完成配对。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/01/pair-request-1024x576.png" alt=""></p><h3 id="使用-gsconnect" tabindex="-1">使用 GSConnect <a class="header-anchor" href="#使用-gsconnect" aria-label="Permalink to “使用 GSConnect”">​</a></h3><p>配对后，你将需要在 Android 设备授予权限，才能使用 GSConnect 上提供的许多功能。单击设备列表中的已配对设备，便可以查看所有可用功能，并根据你的偏好和需要启用或禁用它们。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/01/permissions-1024x576.png" alt=""></p><p>请记住，你还需要在这个 Android 应用程序中授予相应的权限才能使用这些功能。启用权限后，你现在可以访问桌面上的移动联系人，获得消息通知并回复消息，甚至同步桌面和 Android 设备的剪贴板。</p><h3 id="将你的浏览器与-文件-应用集成" tabindex="-1">将你的浏览器与“文件”应用集成 <a class="header-anchor" href="#将你的浏览器与-文件-应用集成" aria-label="Permalink to “将你的浏览器与“文件”应用集成”">​</a></h3><p>GSConnect 允许你直接从计算机上的文件资源管理器的关联菜单向 Android 设备发送文件。</p><p>在 Fedora 的默认 GNOME 桌面上，你需要安装 <code>nautilus-python</code> 依赖包，以便在关联菜单中显示配对的设备。安装此命令非常简单，只需要在你的首选终端运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install nautilus-python</span></span></code></pre></div><p>完成后，将在“<ruby>文件<rt>Files</rt></ruby>”应用的关联菜单中显示“<ruby>发送到移动设备<rt>Send to Mobile Device</rt></ruby>”选项。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/01/send-to-mobile-2-1024x576.png" alt=""></p>',15)),o("p",null,[n[12]||(n[12]=t("同样，为你的浏览器安装相应的 WebExtension，无论是 ",-1)),r(e,{href:"https://addons.mozilla.org/en-US/firefox/addon/gsconnect/"},{default:i(()=>[...n[10]||(n[10]=[t("Firefox",-1)])]),_:1}),n[13]||(n[13]=t(" 还是 ",-1)),r(e,{href:"https://chrome.google.com/webstore/detail/gsconnect/jfnifeihccihocjbfcfhicmmgpjicaec"},{default:i(()=>[...n[11]||(n[11]=[t("Chrome",-1)])]),_:1}),n[14]||(n[14]=t(" 浏览器，都可以将链接发送到你的 Android 设备。你可以选择直接发送链接以在浏览器中直接打开，或将其作为短信息发送。",-1))]),n[34]||(n[34]=o("h3",{id:"运行命令",tabindex:"-1"},[t("运行命令 "),o("a",{class:"header-anchor",href:"#运行命令","aria-label":"Permalink to “运行命令”"},"​")],-1)),n[35]||(n[35]=o("p",null,"GSConnect 允许你定义命令，然后可以从远程设备在计算机上运行这些命令。这使得你可以远程截屏，或者从你的 Android 设备锁定和解锁你的桌面。",-1)),n[36]||(n[36]=o("p",null,[o("img",{src:"https://fedoramagazine.org/wp-content/uploads/2020/01/commands-1024x576.png",alt:""})],-1)),n[37]||(n[37]=o("p",null,"要使用此功能，可以使用标准的 shell 命令和 GSConnect 提供的 CLI。该项目的 GitHub 存储库（CLI Scripting）中提供了有关此操作的文档。",-1)),o("p",null,[r(e,{href:"https://userbase.kde.org/KDE_Connect/Tutorials/Useful_commands"},{default:i(()=>[...n[15]||(n[15]=[t("KDE UserBase Wiki",-1)])]),_:1}),n[16]||(n[16]=t(" 有一个命令示例列表。这些例子包括控制桌面的亮度和音量、锁定鼠标和键盘，甚至更改桌面主题。其中一些命令是针对 KDE Plasma 设计的，需要进行修改才能在 GNOME 桌面上运行。",-1))]),n[38]||(n[38]=o("h3",{id:"探索并享受乐趣",tabindex:"-1"},[t("探索并享受乐趣 "),o("a",{class:"header-anchor",href:"#探索并享受乐趣","aria-label":"Permalink to “探索并享受乐趣”"},"​")],-1)),n[39]||(n[39]=o("p",null,"GSConnect 使我们能够享受到极大的便利和舒适。深入研究首选项，查看你可以做的所有事情，灵活的使用这些命令功能发挥创意，并在下面的评论中自由分享你解锁的新方式。",-1)),n[40]||(n[40]=o("hr",null,null,-1)),o("p",null,[n[18]||(n[18]=t("via: ",-1)),r(e,{href:"https://fedoramagazine.org/connect-fedora-to-your-android-phone-with-gsconnect/"},{default:i(()=>[...n[17]||(n[17]=[t("https://fedoramagazine.org/connect-fedora-to-your-android-phone-with-gsconnect/",-1)])]),_:1})]),o("p",null,[n[23]||(n[23]=t("作者：",-1)),r(e,{href:"https://fedoramagazine.org/author/lowkeyskywalker/"},{default:i(()=>[...n[19]||(n[19]=[t("Lokesh Krishna",-1)])]),_:1}),n[24]||(n[24]=t(" 选题：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...n[20]||(n[20]=[t("lujun9972",-1)])]),_:1}),n[25]||(n[25]=t(" 译者：",-1)),r(e,{href:"https://github.com/chai-yuan"},{default:i(()=>[...n[21]||(n[21]=[t("chai-yuan",-1)])]),_:1}),n[26]||(n[26]=t(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...n[22]||(n[22]=[t("wxy",-1)])]),_:1})]),o("p",null,[n[29]||(n[29]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[27]||(n[27]=[t("LCTT",-1)])]),_:1}),n[30]||(n[30]=t(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...n[28]||(n[28]=[t("Linux中国",-1)])]),_:1}),n[31]||(n[31]=t(" 荣誉推出",-1))])])}const k=a(u,[["render",g]]);export{x as __pageData,k as default};
